import math

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        k = len(target)
        full_mask = (1 << k) - 1

        # pre‑compute lcm for every non‑empty subset of target
        lcm_subset = [0] * (1 << k)
        for mask in range(1, 1 << k):
            l = 1
            for i in range(k):
                if mask >> i & 1:
                    l = l * target[i] // math.gcd(l, target[i])
            lcm_subset[mask] = l

        INF = 10 ** 18
        dp = [INF] * (1 << k)
        dp[0] = 0                     # no target satisfied yet

        for num in nums:
            # cost to turn this num into a multiple of the lcm of each subset
            cost = [0] * (1 << k)
            for mask in range(1, 1 << k):
                L = lcm_subset[mask]
                # next multiple of L that is >= num
                nxt = ((num + L - 1) // L) * L
                cost[mask] = nxt - num

            newdp = dp[:]            # option: skip this num
            for mask in range(1 << k):
                if dp[mask] == INF:
                    continue
                for sub in range(1, 1 << k):
                    new_mask = mask | sub
                    cand = dp[mask] + cost[sub]
                    if cand < newdp[new_mask]:
                        newdp[new_mask] = cand
            dp = newdp

        return dp[full_mask]

