class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if n == 0:
            return -1

        # Since 0 <= nums[i] <= 50, we can use a fixed-size list for counts.
        max_val = 50
        counts = [0] * (max_val + 1)

        # Count the number of subarrays of size k that contain each integer.
        for start in range(n - k + 1):
            subarray = nums[start:start + k]
            unique_vals = set(subarray)          # avoid double‑counting within the same subarray
            for val in unique_vals:
                counts[val] += 1

        # Find the largest integer that appears in exactly one subarray.
        answer = -1
        for val in range(max_val + 1):
            if counts[val] == 1 and val > answer:
                answer = val

        return answer

