class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        if not grid or not grid[0]:
            return []

        rows, cols = len(grid), len(grid[0])
        traversal = []

        for i in range(rows):
            if i % 2 == 0:  # left to right
                for j in range(cols):
                    traversal.append(grid[i][j])
            else:           # right to left
                for j in range(cols - 1, -1, -1):
                    traversal.append(grid[i][j])

        # take every alternate cell starting from the first
        return traversal[::2]

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        i = 0
        while i < n:
            # start of a block of identical characters
            start = i
            ch = s[i]
            while i < n and s[i] == ch:
                i += 1
            # block is s[start:i], length = i - start
            length = i - start
            if length == k:
                left_ok = (start == 0) or (s[start - 1] != ch)
                right_ok = (i == n) or (s[i] != ch)
                if left_ok and right_ok:
                    return True
        return False

