class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Parse events into (timestamp, order, type, data)
        # order: 0 for OFFLINE (processed first), 1 for MESSAGE
        parsed = []
        for ev in events:
            typ, ts_str, data = ev
            ts = int(ts_str)
            order = 0 if typ == "OFFLINE" else 1
            if typ == "OFFLINE":
                user_id = int(data)
                parsed.append((ts, order, typ, user_id))
            else:  # MESSAGE
                mentions_str = data
                parsed.append((ts, order, typ, mentions_str))

        # Sort by timestamp, then by order (OFFLINE before MESSAGE at same timestamp)
        parsed.sort()

        online = [True] * numberOfUsers          # online status
        return_times = []                         # min‑heap of (time_user_becomes_online, user_id)
        mentions = [0] * numberOfUsers

        for ts, _, typ, data in parsed:
            # Bring back any users whose offline period has ended by now
            while return_times and return_times[0][0] <= ts:
                _, uid = heapq.heappop(return_times)
                online[uid] = True

            if typ == "OFFLINE":
                uid = data
                online[uid] = False
                heapq.heappush(return_times, (ts + 60, uid))
            else:  # MESSAGE
                tokens = data.split()
                for token in tokens:
                    if token == "ALL":
                        for uid in range(numberOfUsers):
                            mentions[uid] += 1
                    elif token == "HERE":
                        for uid in range(numberOfUsers):
                            if online[uid]:
                                mentions[uid] += 1
                    elif token.startswith("id"):
                        uid = int(token[2:])

