class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        cnt_k = 0                     # current number of k's in the original array
        max_len = 0                   # longest homogeneous subarray of a value different from k
        cur_val = None                # value of the current run
        cur_len = 0                   # length of the current run

        for num in nums:
            if num == k:
                cnt_k += 1
                # k's break a run of another value, so we reset the current run
                cur_val = None
                cur_len = 0
                continue

            # we are looking at a value different from k
            if num == cur_val:
                cur_len += 1
            else:
                cur_val = num
                cur_len = 1
            if cur_len > max_len:
                max_len = cur_len

        return cnt_k + max_len

