    def maxDistance(self, s: str, k: int) -> int:
        cnt_sw = 0  # number of moves that are either 'S' or 'W'
        cnt_ne = 0  # number of moves that are either 'N' or 'E'
        ans = 0
        for i, ch in enumerate(s, 1):
            if ch == 'S' or ch == 'W':
                cnt_sw += 1
            if ch == 'N' or ch == 'E':
                cnt_ne += 1
            # we can make all moves up to i point north/east (need to change all S/W)
