class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # Store the smallest index for each element value
        min_index = {}
        for idx, val in enumerate(elements):
            if val not in min_index:
                min_index[val] = idx

        result = []
        for g in groups:
            best = math.inf

            # Enumerate all divisors of g
            limit = int(math.isqrt(g))
            for d in range(1, limit + 1):
                if g % d == 0:
                    # Check divisor d
                    if d in min_index and min_index[d] < best:
                        best = min_index[d]
                    # Check the paired divisor g//d
                    other = g // d
                    if other != d and other in min_index and min_index[other] < best:
                        best = min_index[other]

            result.append(-1 if best == math.inf else best)

        return result

