class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        if k == 0:
            return 0

        candidates = []

        for row, limit in zip(grid, limits):
            if limit == 0:
                continue
            # Take the largest 'limit' elements from this row
            # Sorting the row in descending order
            sorted_row = sorted(row, reverse=True)
            # Number of elements we can actually take from this row
            take = min(limit, len(sorted_row))
            candidates.extend(sorted_row[:take])

        # If there are fewer candidates than k, we can only take what's available
        if len(candidates) <= k:
            return sum(candidates)

        # Otherwise, pick the largest k elements from the candidate list
        candidates.sort(reverse=True)
        return sum(candidates[:k])

