class ConvexHull:
    """ Convex hull for lines y = m*x + b, with decreasing slopes,
        supporting queries for minimum y at increasing x values. """
    class Line:
        __slots__ = ('m', 'b')
        def __init__(self, m: int, b: int):
            self.m = m   # slope
            self.b = b   # intercept

        def value(self, x: int) -> int:
            return self.m * x + self.b

    def __init__(self):
        self.hull = []          # deque of lines
        self.pos = 0           # pointer for queries (monotonic x)

    @staticmethod
    def _bad(l1, l2, l3) -> bool:
        # return True if l2 is unnecessary between l1 and l3
        # (b3 - b1)*(m1 - m2) <= (b2 - b1)*(m1 - m3)
        return (l3.b - l1.b) * (l1.m - l2.m) <= (l2.b - l1.b) * (l1.m - l3.m)

    def add_line(self, m: int, b: int):
        new_line = ConvexHull.Line(m, b)
        while len(self.hull) >= 2 and self._bad(self.hull[-2], self.hull[-1], new_line):
            self.hull.pop()
        self.hull.append(new_line)

    def query(self, x: int) -> int:
        # assume x queries are non‑decreasing
        while self.pos + 1 < len(self.hull) and \
              self.hull[self.pos + 1].value(x) <= self.hull[self.pos].value(x):
            self.pos += 1
        return self.hull[self.pos].value(x)


