class Solution:
    def hasSameDigits(self, s: str) -> bool:
        if len(s) == 2:
            return s[0] == s[1]

        # Convert the string into a list of integer digits
        digits = [int(ch) for ch in s]

        # Keep reducing the list until only two digits remain
        while len(digits) > 2:
            next_digits = []
            for i in range(len(digits) - 1):
                summed = (digits[i] + digits[i + 1]) % 10
                next_digits.append(summed)
            digits = next_digits

        # At this point, digits has exactly two elements
        return digits[0] == digits[1]

