class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True

        n = len(s)
        if n == 0:
            return False

        # last occurrence of each character
        last = [0] * 26
        for i, ch in enumerate(s):
            last[ord(ch) - ord('a')] = i

        partitions = 0
        start = 0
        end = 0

        for i, ch in enumerate(s):
            end = max(end, last[ord(ch) - ord('a')])
            if i == end:
                # closed a partition [start, end]
                if end - start + 1 < n:   # not the whole string
                    partitions += 1
                start = i + 1

        # If the whole string forms a single partition, no special substrings exist
        if partitions == 0:
            return k == 0

        return k <= partitions

