class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)

        @lru_cache(None)
        def dp(i: int, carry: int) -> int:
            """
            i     : next index in nums that has NOT been brought to the front yet
            carry: value of the single element (if any) that remained from the previous step.
                    Use -1 to denote that there is no such element.
            """
            has_carry = carry != -1
            remaining_cnt = (1 if has_carry else 0) + (n - i)

            # If 0, 1 or 2 elements are left, we finish in one operation.
            if remaining_cnt <= 2:
                if remaining_cnt == 0:
                    return 0
                # collect the remaining elements
                elems = []
                if has_carry:
                    elems.append(carry)
                elems.extend(nums[i:])
                return max(elems)

            # Build the front three elements.
            front = []
            if has_carry:
                front.append(carry)
            idx = i
            while len(front) < 3:
                front.append(nums[idx])
                idx += 1   # idx will be the new i after we have taken these elements

            best = float('inf')
            # Choose any two of the three to remove.
            for a in range(3):
                for b in range(a + 1, 3):
                    cost = max(front[a], front[b])
                    # the element that stays becomes the new carry
                    for c in range(3):
                        if c != a and c != b:
                            new_carry = front[c]
                            break
                    total = cost + dp(idx, new_carry)
                    if total < best:
                        best = total
            return best

        # start with no carry element; use -1 as sentinel
        return dp(0, -1)

