class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp maps (alternating_sum, parity) -> set of achievable products
        # parity = length of subsequence % 2
        dp = dict()  # use normal dict for the current states

        for num in nums:
            next_dp = defaultdict(set)

            # 1) skip the current number: keep all previous states
            for key, prod_set in dp.items():
                next_dp[key].update(prod_set)

            # 2) start a new subsequence with only this number
            if num <= limit:
                next_dp[(num, 1)].add(num)   # length 1 -> parity 1

            # 3) extend all existing subsequences with the current number
            for (s, p), prod_set in dp.items():
                for prod in prod_set:
                    new_prod = prod * num
                    if new_prod > limit:
                        continue
                    # sign for the current position:
                    # even index (p == 0) -> plus, odd index (p == 1) -> minus
                    new_sum = s + (num if p == 0 else -num)
                    new_par = 1 - p               # length increased by 1
                    next_dp[(new_sum, new_par)].add(new_prod)

            dp = next_dp

        # Find the maximum product among states with alternating sum == k
        best = -1
        for (s, _), prod_set in dp.items():
            if s == k:
                best = max(best, max(prod_set))

        return best

