                    continue

                # remaining odd/even counts after choosing cand
                o_after = o_rem - (cand % 2 == 1)
                e_after = e_rem - (cand % 2 == 0)

                positions_left = n - pos - 1
                if positions_left == 0:
                    cnt = 1
