class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # helper: circular distance between two letters
        def dist(a: str, b: str) -> int:
            da = ord(b) - ord(a)
            da %= 26
            db = ord(a) - ord(b)
            db %= 26
            return da if da < db else db

        # dp[i][j] is an array of length k+1, unsigned short (max length ≤200)
        dp: List[List[array]] = [[array('H', [0] * (k + 1)) for _ in range(n)] for _ in range(n)]

        # length 1 intervals
        for i in range(n):
            dp[i][i][0] = 1

        # intervals of increasing length
        for length in range(2, n + 1):
            for i in range(0, n - length + 1):
                j = i + length - 1
                cost = dist(s[i], s[j])
                for t in range(k + 1):
                    # skip i
                    best = dp[i + 1][j][t]
                    # skip j
                    if dp[i][j - 1][t] > best:
                        best = dp[i][j - 1][t]
                    # match i and j
                    if t >= cost:
                        cand = dp[i + 1][j - 1][t - cost] + 2
                        if cand > best:
                            best = cand
                    dp[i][j][t] = best

        # answer: best length with any budget ≤ k
        return max(dp[0][n - 1][t] for t in range(k + 1))

