class Solution:
    def maxSum(self, nums: List[int]) -> int:
        # Sum of all distinct positive numbers
        positive_distinct_sum = sum({x for x in nums if x > 0})

        # If the sum is positive, we can achieve it by taking one occurrence
        # of each positive distinct value.
        if positive_distinct_sum > 0:
            return positive_distinct_sum

        # Otherwise all numbers are non‑positive.
        # We must choose at least one element, so pick the maximum (least negative) value.
        return max(nums)

