class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        if not fruits:
            return 0

        n = len(baskets)
        size = 1
        while size < n:
            size <<= 1
        seg = [0] * (2 * size)

        # Build segment tree with max values
        for i in range(n):
            seg[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[2 * i], seg[2 * i + 1])

        def update(pos: int) -> None:
            """Set basket at pos to 0 (unavailable) and update the tree."""
            idx = size + pos
            seg[idx] = 0
            idx //= 2
            while idx:
                seg[idx] = max(seg[2 * idx], seg[2 * idx + 1])
                idx //= 2

        def find_leftmost(node: int, node_l: int, node_r: int, need: int) -> int:
            """Return the leftmost index in [node_l, node_r] with capacity >= need.
               Assumes seg[node] >= need.
            """
            if node_l == node_r:
                return node_l
            mid = (node_l + node_r) // 2
            left_child = node * 2
            if seg[left_child] >= need:
                return find_leftmost(left_child, node_l, mid, need)
            else:
                return find_leftmost(left_child + 1, mid + 1, node_r, need)

        unplaced = 0
        for fruit in fruits:
            if seg[1] < fruit:
                # No basket can accommodate this fruit
                unplaced += 1
                continue

            idx = find_leftmost(1, 0, size - 1, fruit)
            # idx might be >= n if the extra leaves (beyond n) have 0 capacity,
            # but seg[1] >= fruit guarantees idx < n.
            update(idx)

        return unplaced

class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        n, m = len(s), len(t)
        max_len = 0

        for i in range(n + 1):
            for j in range(i, n + 1):
                sub_s = s[i:j]            # substring from s (empty if i == j)
                for p in range(m + 1):
                    for q in range(p, m + 1):
                        sub_t = t[p:q]    # substring from t (empty if p == q)
                        combined = sub_s + sub_t
                        if combined == combined[::-1]:
                            max_len = max(max_len, len(combined))

        return max_len

