            for j in range(m):
                if i == 0 and j == 0:
                    cur[j] = skill[i] * mana[j]
                else:
                    left = cur[j - 1] if j > 0 else 0          # finish time of wizard i on potion j-1
                    up = prev[j] if i > 0 else 0              # finish time of wizard i-1 on potion j
