class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Convert each property list to a set of distinct integers
        sets = [set(row) for row in properties]

        # Disjoint Set Union (Union-Find) implementation
        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]  # path compression
                x = parent[x]
            return x

        def union(x: int, y: int) -> None:
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # Build edges based on the intersect condition and union the nodes
        for i in range(n):
            for j in range(i + 1, n):
                # Count distinct common integers
                common = len(sets[i] & sets[j])
                if common >= k:
                    union(i, j)

        # Count unique roots => number of connected components
        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots)

class Solution:
    def reverseDegree(self, s: str) -> int:
        total = 0
        for idx, ch in enumerate(s, start=1):
            # Normal alphabet position: 1 for 'a', 2 for 'b', ..., 26 for 'z'
            normal_pos = ord(ch) - ord('a') + 1
            # Reversed alphabet position: 26 for 'a', 25 for 'b', ..., 1 for 'z'
            reversed_pos = 27 - normal_pos
            total += reversed_pos * idx
        return total

