def solve() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    B = [int(next(it)) for _ in range(N)]
    W = [int(next(it)) for _ in range(M)]

    pos_sum = 0
    pos_zero_cnt = 0
    negatives = []

    for b in B:
        if b > 0:
            pos_sum += b
            pos_zero_cnt += 1
        elif b == 0:
            pos_zero_cnt += 1
        else:
            negatives.append(b)

    negatives.sort(reverse=True)          # e.g., -1, -2, -5, ...
    pref_neg = [0]
    for val in negatives:
        pref_neg.append(pref_neg[-1] + val)

    W.sort(reverse=True)
    pref_w = [0]
    for val in W:
        pref_w.append(pref_w[-1] + val)

    max_k = min(N, M)
    ans = pos_sum  # k = 0 case

    for k in range(1, max_k + 1):
        need_neg = k - pos_zero_cnt
        if need_neg < 0:
            need_neg = 0
        if need_neg > len(negatives):
            continue  # not enough black balls, shouldn't happen
        total = pos_sum + pref_neg[need_neg] + pref_w[k]
        if total > ans:
            ans = total

    print(ans)

