import math

def int_cuberoot(n: int) -> int:
    if n == 0:
        return 0
    x = int(round(n ** (1/3)))
    # adjust due to possible floating point inaccuracies
    while (x + 1) ** 3 <= n:
        x += 1
    while x ** 3 > n:
        x -= 1
    return x

def solve() -> None:
    data = sys.stdin.read().strip()
    if not data:
        return
    N = int(data)

    limit = int_cuberoot(N)
    for d in range(1, limit + 1):
        if N % d != 0:
            continue
        M = N // d  # M = 3y^2 + 3y d + d^2
        # Discriminant of 3y^2 + 3dy + (d^2 - M) = 0
        D = 12 * M - 3 * d * d
        if D < 0:
            continue
        s = math.isqrt(D)
        if s * s != D:
            continue
        # y = (-3d + s) / 6 must be positive integer
        numerator = -3 * d + s
        if numerator <= 0 or numerator % 6 != 0:
            continue
        y = numerator // 6
        if y <= 0:
            continue
        x = y + d
        print(f"{x} {y}")
        return

    print("-1")

