class SegTree:
    def __init__(self, data):
        n = len(data) - 1          # data is 1-indexed
        size = 1
        while size < n:
            size <<= 1
        self.N = size
        self.size = size
        self.seg = [-(10 ** 9)] * (2 * size)
        self.lazy = [0] * (2 * size)
        for i in range(1, n + 1):
            self.seg[size + i - 1] = data[i]
        for i in range(size - 1, 0, -1):
            self.seg[i] = max(self.seg[2 * i], self.seg[2 * i + 1])

    def _push(self, idx):
        if self.lazy[idx]:
            for child in (2 * idx, 2 * idx + 1):
                self.seg[child] += self.lazy[idx]
                self.lazy[child] += self.lazy[idx]
            self.lazy[idx] = 0

    def _add(self, idx, l, r, ql, qr, val):
        if ql > r or qr < l:
            return
        if ql <= l and r <= qr:
            self.seg[idx] += val
            self.lazy[idx] += val
            return
        self._push(idx)
        mid = (l + r) // 2
        self._add(2 * idx, l, mid, ql, qr, val)
        self._add(2 * idx + 1, mid + 1, r, ql, qr, val)
        self.seg[idx] = max(self.seg[2 * idx], self.seg[2 * idx + 1])

    def add(self, l, r, val):
        if l > r:
            return
        self._add(1, 1, self.N, l, r, val)

    def _max(self, idx, l, r, ql, qr):
        if ql > r or qr < l:
            return -(10 ** 9)
        if ql <= l and r <= qr:
            return self.seg[idx]
        self._push(idx)
        mid = (l + r) // 2
        return max(self._max(2 * idx, l, mid, ql, qr),
                   self._max(2 * idx + 1, mid + 1, r, ql, qr))

    def max_query(self, l, r):
        if l > r:
            return -(10 ** 9)
        return self._max(1, 1, self.N, l, r)


