    edge_cnt = sum(1 for v in mapping if v != -1)

    # if every letter must change, there is no spare letter to break cycles
    if edge_cnt == 26:
        print(-1)
        return

    # count cycles in the functional graph defined by mapping
    color = [0] * 26  # 0: unvisited, 1: visiting, 2: visited
    cycles = 0

    sys.setrecursionlimit(10000)

    def dfs(u: int):
        nonlocal cycles
        color[u] = 1
        v = mapping[u]
        if v != -1:
            if color[v] == 0:
                dfs(v)
            elif color[v] == 1:
                # found a new cycle
                cycles += 1
        color[u] = 2

    for i in range(26):
        if mapping[i] != -1 and color[i] == 0:
            dfs(i)

    print(edge_cnt + cycles)


