    pos_h, pos_w = sh, sw

    # pre-allocate dp array
    dp = [[0] * (W + 1) for _ in range(H + 1)]

    def recompute():
        for h in range(1, H + 1):
            for w in range(1, W + 1):
                if h == 1 and w == 1:
                    dp[h][w] = A[h][w]
                elif h == 1:
                    dp[h][w] = dp[h][w - 1] * A[h][w] % MOD
                elif w == 1:
                    dp[h][w] = dp[h - 1][w] * A[h][w] % MOD
                else:
                    dp[h][w] = (dp[h - 1][w] + dp[h][w - 1]) * A[h][w] % MOD

    recompute()
    out_lines = []

    for _ in range(Q):
        d = next(it)
        a = int(next(it)) % MOD
